  ('54da7adb-fe97-48d6-81de-555c19ed5451', 'Bếp ga Rinnai RV-7Si(B) Đen', 'Bếp ga Rinnai RV-7Si(B) màu đen, thiết kế hiện đại, dễ dàng lắp đặt. - Bếp có 2 lò nấu, tiện lợi cho gia đình. - Mặt bếp chống dính, dễ vệ sinh. - Lửa xanh, tiết kiệm ga.', 790000, 'SELL', 'USED', 'ACTIVE', 13, '759/17/26 Hương lộ 2 phương bình trị đông (Phường Bình Trị Đông, TP Hồ Chí Minh mới)', '2026-03-18T16:53:51', '2026-03-18T16:53:51', NULL, '7ee7869c-2e19-4b94-ac99-54bddd50b198', NULL, NULL, NULL, 'cg-0005'),
  ('5cc9b4ca-cc59-4ad2-9e7c-e222aebbe9df', 'Bếp ga âm Capri CR-703KT Đen', 'Bếp ga âm Capri CR-703KT màu đen, thiết kế hiện đại, sang trọng. - Mặt bếp kính cường lực bền đẹp, dễ vệ sinh. - 3 lò nấu tiện lợi, phù hợp gia đình đông người. - An toàn, tiết kiệm ga.', 1100000, 'SELL', 'USED', 'ACTIVE', 145, '759/17/26 Hương lộ 2 phương bình trị đông (Phường Bình Trị Đông, TP Hồ Chí Minh mới)', '2026-03-18T16:55:53', '2026-03-18T16:55:53', NULL, 'd5dae421-132b-4e96-8ea7-b1900680d08e', NULL, NULL, NULL, 'cg-0005'),
  ('8744e042-058e-40c6-aa2b-c9957f0a60a7', 'Bếp ga Torino 2 lò Đen', 'Bếp ga Torino màu đen, thiết kế hiện đại, dễ dàng lắp đặt. - 2 lò nấu tiện lợi. - Đánh lửa tự động, an toàn khi sử dụng. - Mặt bếp dễ vệ sinh.', 950000, 'SELL', 'USED', 'ACTIVE', 348, '759/17/26 Hương lộ 2 phương bình trị đông (Phường Bình Trị Đông, TP Hồ Chí Minh mới)', '2026-03-18T16:57:55', '2026-03-18T16:57:55', NULL, '27d1038c-f2cd-4912-8b6a-4eb7823809da', NULL, NULL, NULL, 'cg-0005'),
